import{_ as t,o,c as r,a2 as a}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md","lastUpdated":1787084291000}'),d={name:"guide/configuration.md"};function i(s,e,n,c,h,l){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>Everything is configured through environment variables, <strong>every one of them optional</strong> — the server works out of the box against the free public OpenStreetMap services. There is no config file and no command-line flag.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>OSM_USER_AGENT</code></td><td><code>osm-mcp/&lt;version&gt; (+https://github.com/ni-c/osm-mcp)</code></td><td>User-Agent sent to every service</td></tr><tr><td><code>NOMINATIM_BASE_URL</code></td><td><code>https://nominatim.openstreetmap.org</code></td><td>Geocoding / reverse geocoding</td></tr><tr><td><code>PHOTON_BASE_URL</code></td><td><code>https://photon.komoot.io</code></td><td>Typo-tolerant geocoding</td></tr><tr><td><code>OSRM_BASE_URL</code></td><td><code>https://routing.openstreetmap.de</code></td><td>Routing, matrices, trip optimization (FOSSGIS layout)</td></tr><tr><td><code>OVERPASS_BASE_URL</code></td><td><code>https://overpass-api.de/…,https://overpass.private.coffee/…</code></td><td>Comma-separated Overpass endpoints, tried in order</td></tr><tr><td><code>VALHALLA_BASE_URL</code></td><td><code>https://valhalla1.openstreetmap.de</code></td><td>Isochrones</td></tr><tr><td><code>ORS_API_KEY</code></td><td>—</td><td>Optional OpenRouteService key (the only secret)</td></tr><tr><td><code>ORS_BASE_URL</code></td><td><code>https://api.openrouteservice.org</code></td><td>OpenRouteService endpoint</td></tr><tr><td><code>OSM_CACHE_TTL</code></td><td><code>3600</code></td><td>Cache TTL in seconds, <code>0</code> disables caching</td></tr></tbody></table><p>See the <a href="/reference/environment">environment reference</a> for the same table with the validation rules.</p><h2 id="osm-user-agent" tabindex="-1"><code>OSM_USER_AGENT</code> <a class="header-anchor" href="#osm-user-agent" aria-label="Permalink to &quot;`OSM_USER_AGENT`&quot;">​</a></h2><p>The <a href="https://operations.osmfoundation.org/policies/nominatim/" target="_blank" rel="noreferrer">Nominatim usage policy</a> requires a real, identifying User-Agent, so the server always sends one — the default identifies the project and links to its repository. Set your own if you run this at any scale, so the service operators can reach <em>you</em> rather than the project when something misbehaves.</p><h2 id="the-base-url-variables" tabindex="-1">The <code>*_BASE_URL</code> variables <a class="header-anchor" href="#the-base-url-variables" aria-label="Permalink to &quot;The `*_BASE_URL` variables&quot;">​</a></h2><p>Each backend can be pointed at a self-hosted instance — the supported path for heavy, commercial or privacy-sensitive use. All of them are validated at startup; the server <strong>exits</strong> with a <code>ConfigError</code> when a URL is:</p><ul><li>unparseable,</li><li>not <code>http://</code> or <code>https://</code>,</li><li>carrying credentials in the form <code>https://user:pass@host</code> — those would end up in logs and error messages,</li><li>or carrying a query string or fragment, which would produce malformed request URLs and could smuggle a token into error output.</li></ul><p>Trailing slashes are stripped. Plain <code>http://</code> to a <strong>non-loopback</strong> host produces a warning on stderr and keeps going; loopback (<code>localhost</code>, <code>*.localhost</code>, <code>127.*</code>, <code>::1</code>) does not warn.</p><div class="warning custom-block"><p class="custom-block-title">OSRM needs the FOSSGIS layout</p><p><code>OSRM_BASE_URL</code> must serve the <code>routed-car</code> / <code>routed-bike</code> / <code>routed-foot</code> path prefixes, i.e. one host that fronts three profile-specific OSRM instances — the layout of the FOSSGIS demo server. A plain single-profile OSRM will not answer these paths. See the <a href="/guide/faq">FAQ</a> for why this exists.</p></div><p><code>OVERPASS_BASE_URL</code> takes a <strong>comma-separated list</strong> of interpreter endpoints. They are tried in order: a 429 or 5xx from one endpoint fails over to the next, which is how the default configuration survives the main instance being busy.</p><h2 id="ors-api-key" tabindex="-1"><code>ORS_API_KEY</code> <a class="header-anchor" href="#ors-api-key" aria-label="Permalink to &quot;`ORS_API_KEY`&quot;">​</a></h2><p>The only secret, and it is optional. When set, <code>route</code>, <code>route_matrix</code> and <code>isochrone</code> switch from the shared OSRM/Valhalla demo servers to <a href="https://openrouteservice.org" target="_blank" rel="noreferrer">OpenRouteService</a>, which gives you a per-key quota (free tier: 2 000 directions/day, 40/minute) instead of shared best-effort capacity. <code>optimize_route</code> always uses OSRM — ORS has no equivalent of the OSRM <code>/trip</code> service in its core API.</p><p>Handling, because it is a secret:</p><ul><li><strong>Removed from <code>process.env</code> immediately after loading</strong> — before any validation can throw — so it is not visible to child processes or in <code>/proc/&lt;pid&gt;/environ</code> even when the server keeps running after a caught configuration error.</li><li><strong>Redacted from error messages</strong> before they reach the model context.</li><li><strong>Refused over cleartext:</strong> the server exits if <code>ORS_BASE_URL</code> is a plain <code>http://</code> non-loopback URL while a key is set, because the key travels in an <code>Authorization</code> header.</li></ul><h2 id="osm-cache-ttl" tabindex="-1"><code>OSM_CACHE_TTL</code> <a class="header-anchor" href="#osm-cache-ttl" aria-label="Permalink to &quot;`OSM_CACHE_TTL`&quot;">​</a></h2><p>Identical upstream requests are served from an in-memory cache for this many seconds (default one hour, at most 500 entries, responses over 1 MB are never cached). Caching is not just a speed-up here — the Nominatim policy explicitly asks clients to cache results. <code>0</code> disables it, e.g. against a rapidly-changing self-hosted instance.</p><p>Must be a plain number of seconds; anything else is a startup error. The invalid value itself is deliberately not echoed in the error message — an API key pasted into the wrong variable would otherwise be printed into the MCP host&#39;s log.</p><h2 id="fixed-behaviour" tabindex="-1">Fixed behaviour <a class="header-anchor" href="#fixed-behaviour" aria-label="Permalink to &quot;Fixed behaviour&quot;">​</a></h2><p>Not configurable, deliberately:</p><table tabindex="0"><thead><tr><th>Behaviour</th><th>Value</th><th>Why</th></tr></thead><tbody><tr><td>Rate limit, per service</td><td>~1 request/second</td><td>Nominatim and FOSSGIS policies ask for exactly that</td></tr><tr><td>ORS rate limit</td><td>~40 requests/minute</td><td>The ORS free-tier per-minute quota</td></tr><tr><td>Overpass concurrency</td><td>2 requests</td><td>The public instance grants ~2 slots per IP</td></tr><tr><td>Request timeout</td><td>30 s (Overpass: 40 s)</td><td>A hung request would hang the tool call</td></tr><tr><td>HTTP redirects</td><td>never followed</td><td>A redirect would replay headers at whatever host it names</td></tr><tr><td>Matrix size</td><td>origins + destinations ≤ 25</td><td>Stays within the public OSRM usage policy</td></tr><tr><td>Turn-by-turn steps</td><td>first 100</td><td>A continental route has tens of thousands of steps</td></tr><tr><td>POI tags in <code>poi_details</code></td><td>60 tags, 500 chars each</td><td>Mega-relations carry hundreds of tags</td></tr></tbody></table>',22)])])}const g=t(d,[["render",i]]);export{u as __pageData,g as default};
